// Parse last-run timestamp, target folder, modified-only flag, and Awaiting Decision flags
// from Obsidian Housekeeping.md
const content = $input.item.json.body ?? $input.item.json.data ?? '';

// --- Parse last-run timestamp ---
const oneYearAgo = new Date(Date.now() - 365 * 24 * 60 * 60 * 1000).toISOString();
const timestampMatch = content.match(/\*\*Last run:\*\*\s*([^\n]+)/);
let lastRun = null;
let lastRunIso = null;

if (timestampMatch) {
  const raw = timestampMatch[1].trim();
  if (raw === '—' || raw === '-' || raw === '') {
    lastRunIso = oneYearAgo;
    lastRun = 'NOT SET – fell back to 1 year ago';
  } else {
    const parsed = new Date(raw);
    if (!isNaN(parsed.getTime())) {
      lastRunIso = parsed.toISOString();
      lastRun = raw;
    } else {
      lastRunIso = oneYearAgo;
      lastRun = `INVALID ("${raw}") – fell back to 1 year ago`;
    }
  }
} else {
  lastRunIso = oneYearAgo;
  lastRun = 'NOT FOUND – fell back to 1 year ago';
}

// --- Parse Awaiting Decision flags ---
const awaitingSection = content.match(/## Awaiting Decision\n([\s\S]*?)(?=\n## |$)/);
const awaitingRaw = awaitingSection ? awaitingSection[1].trim() : '';

const flags = [];
let match;

// New callout format: > [!question] `path`\n> description
const calloutPattern = /^> \[!question\] ([^\n]+)\n> (.+?)$/gm;
while ((match = calloutPattern.exec(awaitingRaw)) !== null) {
  flags.push({ filePath: match[1], description: match[2].trim() });
}

// Legacy format: - `path` — description (fallback for existing items)
const flagPattern = /^- `([^`]+)` — (.+?)$/gm;
while ((match = flagPattern.exec(awaitingRaw)) !== null) {
  const filePath = match[1];
  const description = match[2].trim();
  // Only add if not already captured by callout pattern
  if (!flags.some(f => f.filePath === filePath && f.description === description)) {
    flags.push({ filePath, description });
  }
}

// --- Parse Ignored flags ---
const ignoredSection = content.match(/## Ignored\n([\s\S]*?)(?=\n## |$)/);
const ignoredRaw = ignoredSection ? ignoredSection[1].trim() : '';

const ignoredFlags = [];
const ignoredPattern = /^- `([^`]+)` — (.+?)$/gm;
let ignoredMatch;
while ((ignoredMatch = ignoredPattern.exec(ignoredRaw)) !== null) {
  ignoredFlags.push({ filePath: ignoredMatch[1], description: ignoredMatch[2].trim() });
}
// Also match callout format in Ignored section
const ignoredCalloutPattern = /^> \[!question\] ([^\n]+)\n> (.+?)$/gm;
let ignoredCalloutMatch;
while ((ignoredCalloutMatch = ignoredCalloutPattern.exec(ignoredRaw)) !== null) {
  const fp = ignoredCalloutMatch[1];
  const desc = ignoredCalloutMatch[2].trim();
  if (!ignoredFlags.some(f => f.filePath === fp && f.description === desc)) {
    ignoredFlags.push({ filePath: fp, description: desc });
  }
}

const pendingCount = flags.length;
const actionableCount = 0;

// --- Parse target folder (under ## Config) ---
const targetFolderMatch = content.match(/\*\*Target folder:\*\*\s*`([^`]+)`/);
const targetFolder = targetFolderMatch ? targetFolderMatch[1].trim() : null;

// --- Parse process-modified-only checkbox (under ## Config) ---
const modifiedOnlyMatch = content.match(/- \[([ x])\] Process modified files only/);
const processModifiedOnly = modifiedOnlyMatch ? modifiedOnlyMatch[1] === 'x' : true;

// --- Parse Area Map (under ## Config > ### Area Map) ---
// Format: - Folder Name | area-slug | Display Name
const areaMapSection = content.match(/### Area Map\n[\s\S]*?(?=\n---\n|\n## )/);
const areaMapRaw = areaMapSection ? areaMapSection[0] : '';
const areaMap = {}; // folderName -> { slug, displayName }
const areaMapPattern = /^- (.+?) \| (.+?) \| (.+?)$/gm;
let areaMapMatch;
while ((areaMapMatch = areaMapPattern.exec(areaMapRaw)) !== null) {
  areaMap[areaMapMatch[1].trim()] = {
    slug: areaMapMatch[2].trim(),
    displayName: areaMapMatch[3].trim()
  };
}

console.log(`Last run: ${lastRun}`);
console.log(`Target folder from control file: ${targetFolder ?? '(not set – will use Config fallback)'}`);
console.log(`Process modified only: ${processModifiedOnly}`);
console.log(`Awaiting Decision flags: ${flags.length} total, ${pendingCount} pending`);

return [{
  controlFileContent: content,
  lastRun,
  lastRunIso,
  targetFolder,
  processModifiedOnly,
  areaMap,
  awaitingFlags: flags,
  ignoredFlags,
  flagSummary: { total: flags.length, actionable: 0, pending: pendingCount },
  runStarted: new Date().toISOString()
}];

