  const tf = $('Parse Timestamp & Flags').item.json.targetFolder;
  const vp = $('Config').item.json.vaultPath.replace(/\/$/, '');
  const fallback = $('Config').item.json.targetPath;
  const folder = tf ? `${vp}/${tf}` : fallback;
  const modOnly = $('Parse Timestamp & Flags').item.json.processModifiedOnly;
  const ts = new Date($('Parse Timestamp & Flags').item.json.lastRunIso)
    .toISOString().replace('T', ' ').replace(/\.\d{3}Z$/, '');
  return modOnly
    ? `find "${folder}" -name "*.md" -newermt "${ts}" | sort`
    : `find "${folder}" -name "*.md" | sort`;
})() }}

