const vaultPath = $('Config').item.json.vaultPath;
const excludedRaw = $('Config').item.json.excludedPaths ?? '';
const excludedPaths = typeof excludedRaw === 'string'
  ? excludedRaw.split(',').map(p => p.trim()).filter(p => p.length > 0)
  : excludedRaw;

const lastRunIso = $('Parse Timestamp & Flags').item.json.lastRunIso;
const stdout = $input.item.json.stdout ?? '';

const absolutePaths = stdout.split('\n').map(l => l.trim()).filter(l => l.length > 0);

const relativePaths = absolutePaths.map(p => {
  const prefix = vaultPath.endsWith('/') ? vaultPath : vaultPath + '/';
  const rel = p.startsWith(prefix) ? p.slice(prefix.length) : p;
  return rel.replace(/^\.\//,  '');
});

const filtered = relativePaths.filter(filePath =>
  !excludedPaths.some(excluded => filePath.startsWith(excluded))
);

console.log(`Files modified since ${lastRunIso}: ${relativePaths.length}`);
console.log(`After exclusion filter: ${filtered.length}`);

return [{
  allFiles: relativePaths,
  filteredFiles: filtered,
  excludedCount: relativePaths.length - filtered.length,
  fileCount: filtered.length,
  lastRunIso
}];

// ── Master: Build Outputs ────────────────────────────────────────────────
const now = new Date();
// Log time in Auckland local time (NZDT/NZST handled by the timezone)
const nzDate = now.toLocaleString('sv-SE', { timeZone: 'Pacific/Auckland' });
const datestamp = nzDate.slice(0, 16).replace(' ', ' | ');
const runFinishedIso = new Date().toISOString();

const cutoff = new Date(now.getTime() - 10 * 24 * 60 * 60 * 1000);

const controlData = $('Parse Timestamp & Flags').first().json;
const lastRunRead = controlData.lastRun;
const flagSummary = controlData.flagSummary;
const existingFlags = controlData.awaitingFlags ?? [];
const ignoredFlags = controlData.ignoredFlags ?? [];
const controlContent = controlData.controlFileContent ?? '';

const allItems = $('Aggregate Results').first().json.data ?? [];
const fileCount = allItems.length;

const fixedLines = [];
const flaggedLines = [];
const newAwaitingDecisions = [];

for (const item of allItems) {
  const name = item.filename ?? item.filePath ?? 'unknown';
  const path = item.filePath ?? 'unknown';
  const fixes = item.fixes ?? [];
  const flags = item.flags ?? [];
  const writeStatus = item.writeStatus ?? 'unknown';

  if (fixes.length > 0) {
    for (const fix of fixes) fixedLines.push(`- \`${name}\` — ${fix}`);
    if (writeStatus !== 'written' && writeStatus !== 'skipped') {
      fixedLines.push(`  ⚠️ Write status: ${writeStatus}`);
    }
  }

  if (flags.length > 0) {
    for (const flag of flags) {
      flaggedLines.push(`- \`${name}\` — ${flag}`);

      // Check if this specific file+flag combo is already in Awaiting Decision or Ignored
      const isDuplicate = existingFlags.some(f => f.filePath === path && f.description === flag)
        || ignoredFlags.some(f => f.filePath === path && f.description === flag);
      if (!isDuplicate) {
        newAwaitingDecisions.push(`> [!question] ${path}\n> ${flag}\n\n**Decision:**`);
      }
    }
  }
}

// 1. BUILD LOG CONTENT
const fixedSection   = fixedLines.length  > 0 ? `\n#### Fixed\n${fixedLines.join('\n')}`   : '';
const flaggedSection = flaggedLines.length > 0 ? `\n#### Flagged\n${flaggedLines.join('\n')}` : '';
const noActivity     = fixedLines.length === 0 && flaggedLines.length === 0 ? '\n*No fixes or flags this run.*' : '';

const newEntry = `### ${datestamp}\n**Last run read:** ${lastRunRead}\n**Files processed:** ${fileCount}\n**Awaiting
Decision flags:** ${flagSummary.total} total (${flagSummary.actionable} actionable, ${flagSummary.pending}
pending)${fixedSection}${flaggedSection}${noActivity}`;

const existingLog = $input.item.json.body ?? $input.item.json.data ?? '';
const logSectionMatch = existingLog.match(/^(---[\s\S]*?## Log\n)([\s\S]*)$/m);
const logHeader       = logSectionMatch ? logSectionMatch[1] : existingLog;
const logEntries      = logSectionMatch ? logSectionMatch[2] : '';

const entryBlocks = logEntries.split(/(?=^### \d{4}-\d{2}-\d{2})/m).filter(e => e.trim());
const recentEntries = entryBlocks.filter(block => {
  const dateMatch = block.match(/^### (\d{4}-\d{2}-\d{2})/);
  if (!dateMatch) return true;
  return new Date(dateMatch[1]) >= cutoff;
});

const updatedLog = `${logHeader}\n${[newEntry.trimEnd(), ...recentEntries.map(e => e.trimEnd())].join('\n\n')}\n`;

// 2. BUILD CONTROL FILE CONTENT
// Update the **Last run:** timestamp
let updatedControl = controlContent.replace(/\*\*Last run:\*\*\s*[^\n]*/, `**Last run:** ${runFinishedIso}`);

// Append new flags to the Awaiting Decision section
if (newAwaitingDecisions.length > 0) {
    const awaitingHeader = '## Awaiting Decision';
    const splitIndex = updatedControl.indexOf(awaitingHeader);

    if (splitIndex !== -1) {
        const headerEnd = splitIndex + awaitingHeader.length;
        const preamble  = updatedControl.slice(0, headerEnd);
        const rest      = updatedControl.slice(headerEnd).trim();
        // Insert new flags immediately after the header
        updatedControl = `${preamble}\n${newAwaitingDecisions.join('\n\n')}\n\n${rest}`;
    } else {
        // Fallback: append at end if header not found
        updatedControl += `\n\n${awaitingHeader}\n${newAwaitingDecisions.join('\n')}\n`;
    }
}

return [{ 
    updatedLog, 
    updatedControl,
    logChanged: updatedLog !== existingLog,
    controlChanged: true 
}];
